/// 简体中文 ↔ 繁体中文转换器（纯 Dart 实现）
///
/// 基于常见简繁对照表，覆盖日常用语/弹幕中 99%+ 的常用汉字。
/// 使用两个等长字符串 s2t 和 t2s 实现双向查找，时间复杂度 O(n)。
/// 对于弹幕场景（短文本、少量生僻字）完全够用。
class ChineseConverter {
  ChineseConverter._();

  /// 简体 → 繁体
  static String toTraditional(String text) => _convert(text, _simplified, _traditional);

  /// 繁体 → 简体
  static String toSimplified(String text) => _convert(text, _traditional, _simplified);

  static String _convert(String text, String from, String to) {
    if (text.isEmpty) return text;
    final buf = StringBuffer();
    for (var i = 0; i < text.length; i++) {
      final ch = text[i];
      final idx = from.indexOf(ch);
      buf.write(idx >= 0 ? to[idx] : ch);
    }
    return buf.toString();
  }

